#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    // adjacency: (neighbor w, 1 if the original edge points w->v and must be reversed when v is the parent)
    vector<vector<pair<int, int>>> g(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        g[a].push_back({b, 0});
        g[b].push_back({a, 1});
    }
    vector<int> parent(n, -1), cost(n, 0), order = {0};
    long long initial = 0;
    for (size_t k = 0; k < order.size(); k++) {
        int v = order[k];
        for (auto [w, rev] : g[v]) {
            if (w == parent[v]) continue;
            parent[w] = v;
            cost[w] = rev;
            initial += rev;
            order.push_back(w);
        }
    }
    // Rerooting across one edge changes the cost by exactly +1 or -1.
    vector<long long> ans(n, initial);
    long long best = initial;
    for (size_t k = 1; k < order.size(); k++) {
        int v = order[k];
        ans[v] = ans[parent[v]] + 1 - 2 * cost[v];
        best = min(best, ans[v]);
    }
    printf("%lld\n", best);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int m = 2 * (n - 1);
        int[] head = new int[n], nxt = new int[m], to = new int[m], rv = new int[m];
        Arrays.fill(head, -1);
        int ec = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = nextInt(), b = nextInt();
            to[ec] = b; rv[ec] = 0; nxt[ec] = head[a]; head[a] = ec++;
            to[ec] = a; rv[ec] = 1; nxt[ec] = head[b]; head[b] = ec++;
        }
        int[] parent = new int[n], cost = new int[n], order = new int[n];
        Arrays.fill(parent, -1);
        int sz = 0;
        order[sz++] = 0;
        long initial = 0;
        for (int k = 0; k < sz; k++) {
            int v = order[k];
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (w == parent[v]) continue;
                parent[w] = v;
                cost[w] = rv[e];
                initial += rv[e];
                order[sz++] = w;
            }
        }
        // Rerooting across one edge changes the cost by exactly +1 or -1.
        long[] ans = new long[n];
        ans[0] = initial;
        long best = initial;
        for (int k = 1; k < sz; k++) {
            int v = order[k];
            ans[v] = ans[parent[v]] + 1 - 2 * cost[v];
            best = Math.min(best, ans[v]);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

type edge struct{ to, rev int }

func main() {
	n := readInt()
	g := make([][]edge, n)
	for i := 0; i < n-1; i++ {
		a, b := readInt(), readInt()
		g[a] = append(g[a], edge{b, 0})
		g[b] = append(g[b], edge{a, 1})
	}
	parent := make([]int, n)
	for i := range parent {
		parent[i] = -1
	}
	cost := make([]int, n)
	order := []int{0}
	initial := 0
	for k := 0; k < len(order); k++ {
		v := order[k]
		for _, e := range g[v] {
			if e.to == parent[v] {
				continue
			}
			parent[e.to] = v
			cost[e.to] = e.rev
			initial += e.rev
			order = append(order, e.to)
		}
	}
	// Rerooting across one edge changes the cost by exactly +1 or -1.
	ans := make([]int, n)
	ans[0] = initial
	best := initial
	for _, v := range order[1:] {
		ans[v] = ans[parent[v]] + 1 - 2*cost[v]
		best = min(best, ans[v])
	}
	fmt.Println(best)
}
